"use client";

import { useCallback, useEffect, useMemo, useState, type ChangeEvent, type FormEvent, type ReactNode } from "react";
import { BadgeDollarSign, BadgePercent, Boxes, Check, ChevronDown, ChevronRight, CircleUserRound, FileText, Image, LayoutDashboard, LogOut, PackageCheck, Plus, RefreshCw, Save, Settings, Shirt, Star, Store, Trash2, Upload, X } from "lucide-react";
import type { PriceAddon, PriceEntry, PriceGroup } from "@/lib/pricing";
import type { StoreSection } from "@/lib/catalog";
import { money } from "@/lib/catalog";
import ThemeToggle from "@/components/ThemeToggle";

const api = process.env.NEXT_PUBLIC_API_URL || "http://localhost:8000/api";
type Order = { id: number; order_number: string; customer_name: string; phone: string; district: string; address: string; total: number; delivery_charge: number; status: string; payment_status: string; payment_method: string; courier?: string; courier_tracking_code?: string; courier_tracking_url?: string; items: Array<{ product_name: string; quantity: number }> };
type ProductRow = { id: number; slug: string; name: string; club: string; category: string; description: string; price: number; image_url: string; edition: string; stock: number; variants: { sizes?: string[] }; meta_title?: string; meta_description?: string; is_active: boolean };
type Banner = { id: number; title: string; subtitle?: string; desktop_image: string; mobile_image?: string; button_label?: string; button_url?: string; is_active: boolean };
type MediaFile = { name: string; url: string; size: number };
type Coupon = { id: number; code: string; type: "fixed" | "percent"; value: number; min_order: number; is_active: boolean; expires_at?: string | null };
type Review = { id: number; customer_name: string; district: string; review: string; photo_url?: string; rating: number; is_verified: boolean; is_published: boolean };
type Settings = Record<string, string>;
type Zone = { name: string; charge: number; is_active: boolean };
type Panel = "overview" | "orders" | "products" | "homepage" | "product_page" | "pricing" | "footer" | "media" | "coupons" | "reviews" | "settings";

const navigation: Array<{ id: Panel; label: string; icon: typeof Store }> = [
  { id: "overview", label: "Overview", icon: LayoutDashboard }, { id: "orders", label: "Orders", icon: PackageCheck },
  { id: "products", label: "Products", icon: Boxes }, { id: "homepage", label: "Homepage", icon: Store },
  { id: "product_page", label: "Product page", icon: Shirt }, { id: "pricing", label: "Pricing table", icon: BadgeDollarSign },
  { id: "footer", label: "Footer", icon: FileText }, { id: "media", label: "Media library", icon: Image }, { id: "settings", label: "Store settings", icon: Settings },
  { id: "coupons", label: "Coupons", icon: BadgePercent }, { id: "reviews", label: "Reviews", icon: Star },
];
const inputClass = "w-full rounded-lg border border-slate-200 bg-white px-3 py-2.5 text-sm text-slate-900 outline-none placeholder:text-slate-400 focus:border-lime-600 focus:ring-2 focus:ring-lime-100";
const labelClass = "mb-1.5 block text-xs font-semibold text-slate-600";

function Field({ label, children, className = "" }: { label: string; children: ReactNode; className?: string }) { return <label className={`block ${className}`}><span className={labelClass}>{label}</span>{children}</label>; }

function ImageUpload({ value, onChange, token, label = "Image" }: { value: string; onChange: (url: string) => void; token: string; label?: string }) {
  const [busy, setBusy] = useState(false); const [error, setError] = useState("");
  const upload = async (event: ChangeEvent<HTMLInputElement>) => { const file = event.target.files?.[0]; if (!file) return; setBusy(true); setError(""); const form = new FormData(); form.set("file", file); try { const response = await fetch(`${api}/admin/media`, { method: "POST", headers: { authorization: `Bearer ${token}` }, body: form }); const payload = await response.json().catch(() => ({})); if (!response.ok) throw new Error(payload.message || "Image upload failed"); onChange(payload.data.url); } catch (cause) { setError(cause instanceof Error ? cause.message : "Image upload failed"); } finally { setBusy(false); event.target.value = ""; } };
  return <div><span className={labelClass}>{label}</span><div className="flex gap-3"><div className="grid h-[68px] w-[78px] shrink-0 place-items-center overflow-hidden rounded-lg border border-slate-200 bg-slate-50">{value ? <img src={value} alt="Preview" className="h-full w-full object-cover"/> : <Image size={20} className="text-slate-300"/>}</div><div className="min-w-0 flex-1"><input value={value} onChange={(event) => onChange(event.target.value)} className={inputClass} placeholder="Paste image URL or upload"/><label className="mt-2 inline-flex cursor-pointer items-center gap-1.5 rounded-md border border-slate-200 bg-white px-2.5 py-1.5 text-[11px] font-semibold text-slate-600 hover:bg-slate-50"><Upload size={13}/>{busy ? "Uploading…" : "Upload image"}<input type="file" accept="image/jpeg,image/png,image/webp" onChange={upload} className="hidden" disabled={busy}/></label>{error && <span className="ml-2 text-[10px] text-red-600">{error}</span>}</div></div></div>;
}

export default function AdminPage() {
  const [token, setToken] = useState(""); const [email, setEmail] = useState(""); const [password, setPassword] = useState(""); const [panel, setPanel] = useState<Panel>("overview");
  const [loading, setLoading] = useState(false); const [saving, setSaving] = useState(false); const [error, setError] = useState(""); const [notice, setNotice] = useState("");
  const [orders, setOrders] = useState<Order[]>([]); const [products, setProducts] = useState<ProductRow[]>([]); const [banners, setBanners] = useState<Banner[]>([]); const [coupons, setCoupons] = useState<Coupon[]>([]); const [reviews, setReviews] = useState<Review[]>([]); const [sections, setSections] = useState<Record<string, StoreSection[]>>({ home: [], product: [] }); const [groups, setGroups] = useState<PriceGroup[]>([]); const [settings, setSettings] = useState<Settings>({}); const [zones, setZones] = useState<Zone[]>([]); const [media, setMedia] = useState<MediaFile[]>([]); const [reviewPhoto, setReviewPhoto] = useState("");
  const [productForm, setProductForm] = useState<Partial<ProductRow>>({ slug: "", name: "", club: "", category: "Fan Edition", description: "", price: 18, image_url: "", edition: "Fan Edition", stock: 50, variants: { sizes: ["S", "M", "L", "XL", "XXL"] }, meta_title: "", meta_description: "" });
  const [editingProduct, setEditingProduct] = useState<number | null>(null); const [bannerForm, setBannerForm] = useState<Partial<Banner>>({ title: "", subtitle: "", desktop_image: "", mobile_image: "", button_label: "Shop now", button_url: "/#shop" });
  const request = useCallback(async (path: string, init: RequestInit = {}) => { const response = await fetch(`${api}${path}`, { ...init, headers: { authorization: `Bearer ${token}`, ...(init.body ? { "content-type": "application/json" } : {}), ...init.headers } }); const body = await response.json().catch(() => ({})); if (!response.ok) throw new Error(body.message || `Request failed (${response.status})`); return body; }, [token]);
  const load = useCallback(async () => { if (!token) return; setLoading(true); setError(""); try { const [o, p, b, cp, rv, s, c, st, m] = await Promise.all([request("/admin/orders"), request("/admin/products"), request("/admin/banners"), request("/admin/coupons"), request("/admin/reviews"), request("/admin/sections"), request("/admin/pricing"), request("/admin/settings"), request("/admin/media")]); setOrders(o.data || []); setProducts(p.data || []); setBanners(b.data || []); setCoupons(cp.data || []); setReviews(rv.data || []); setSections(s.data || { home: [], product: [] }); setGroups(c.data || []); setSettings(st.settings || {}); setZones(st.delivery_zones || []); setMedia(m.data || []); } catch (cause) { setError(cause instanceof Error ? cause.message : "Could not load dashboard data."); } finally { setLoading(false); } }, [request, token]);
  useEffect(() => { const saved = sessionStorage.getItem("tr-admin-token"); if (saved) setToken(saved); }, []);
  useEffect(() => { if (token) void load(); }, [token, load]);
  const login = async (event: FormEvent) => { event.preventDefault(); setError(""); setSaving(true); try { const response = await fetch(`${api}/admin/login`, { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify({ email, password }) }); const body = await response.json().catch(() => ({})); if (!response.ok) throw new Error(body.message || "Admin sign in failed."); sessionStorage.setItem("tr-admin-token", body.token); setToken(body.token); setPassword(""); } catch (cause) { setError(cause instanceof Error ? cause.message : "Could not sign in."); } finally { setSaving(false); } };
  const logout = async () => { try { await request("/admin/logout", { method: "POST" }); } catch { /* The local session can still be cleared. */ } sessionStorage.removeItem("tr-admin-token"); setToken(""); };
  async function save(path: string, method: string, value: unknown, success = "Changes saved.") { setSaving(true); setError(""); setNotice(""); try { await request(path, { method, body: JSON.stringify(value) }); setNotice(success); await load(); } catch (cause) { setError(cause instanceof Error ? cause.message : "Could not save changes."); } finally { setSaving(false); } }
  const updateSettings = (key: string, value: string) => setSettings((current) => ({ ...current, [key]: value }));
  const updateSection = (page: "home" | "product", index: number, change: Partial<StoreSection>) => setSections((current) => ({ ...current, [page]: current[page].map((item, i) => i === index ? { ...item, ...change } : item) }));
  const createProduct = async (event: FormEvent) => { event.preventDefault(); const payload = { ...productForm, variants: productForm.variants || { sizes: ["S", "M", "L", "XL", "XXL"] }, is_active: true }; await save(editingProduct ? `/admin/products/${editingProduct}` : "/admin/products", editingProduct ? "PUT" : "POST", payload, editingProduct ? "Product updated." : "Product created."); setEditingProduct(null); setProductForm({ slug: "", name: "", club: "", category: "Fan Edition", description: "", price: 18, image_url: "", edition: "Fan Edition", stock: 50, variants: { sizes: ["S", "M", "L", "XL", "XXL"] }, meta_title: "", meta_description: "" }); };
  const addSection = (page: "home" | "product") => { const key = page === "home" ? `new_section_${Date.now()}` : `product_section_${Date.now()}`; setSections((current) => ({ ...current, [page]: [...current[page], { page, section_key: key, title: "New section", subtitle: "", body: "", image_url: "", mobile_image_url: "", button_label: "", button_url: "", sort_order: current[page].length * 10, is_active: true }] })); };
  const saveSections = (page: "home" | "product") => void save("/admin/sections", "PUT", { page, sections: sections[page] }, `${page === "home" ? "Homepage" : "Product page"} sections saved.`);
  const dashboardCounts = useMemo(() => ({ orders: orders.length, products: products.length, pending: orders.filter((order) => order.payment_status !== "paid").length, value: orders.reduce((sum, order) => sum + Number(order.total || 0), 0) }), [orders, products]);
  const updateOrder = async (order: Order, patch: Partial<Order>) => save(`/admin/orders/${order.id}`, "PATCH", patch, `${order.order_number} updated.`);

  if (!token) return <main className="admin-shell grid min-h-screen place-items-center bg-slate-100 px-4 py-10 text-slate-900"><ThemeToggle compact/><form onSubmit={login} className="w-full max-w-[420px] rounded-2xl border border-slate-200 bg-white p-7 shadow-xl sm:p-9"><div className="flex items-center gap-3"><img src="/brand/tr-crest.webp" className="h-11 w-11 rounded-full object-cover" alt="TR Sports Line"/><div><div className="text-xs font-bold uppercase tracking-widest text-lime-700">TR Sports Line</div><div className="text-[11px] text-slate-500">Store administration</div></div></div><h1 className="mt-8 text-2xl font-bold tracking-tight">Sign in to your dashboard</h1><p className="mt-2 text-sm leading-6 text-slate-500">Manage products, orders, pricing, pages and store media.</p><Field label="Admin email" className="mt-6"><input required type="email" autoComplete="username" value={email} onChange={(event) => setEmail(event.target.value)} className={inputClass} placeholder="admin@example.com"/></Field><Field label="Password" className="mt-4"><input required type="password" autoComplete="current-password" value={password} onChange={(event) => setPassword(event.target.value)} className={inputClass} placeholder="Your admin password"/></Field>{error && <p role="alert" className="mt-4 rounded-lg bg-red-50 p-3 text-xs text-red-700">{error}</p>}<button disabled={saving} className="mt-6 flex w-full items-center justify-center gap-2 rounded-lg bg-slate-900 px-4 py-3 text-sm font-bold text-white hover:bg-slate-800 disabled:opacity-60">{saving ? "Signing in…" : "Sign in"}<ChevronRight size={16}/></button><p className="mt-5 text-[11px] leading-5 text-slate-400">Create the first dashboard user with <code className="rounded bg-slate-100 px-1">php artisan admin:create-user</code> inside the Laravel folder.</p></form></main>;

  const current = navigation.find((item) => item.id === panel)!;
  return <main className="admin-shell min-h-screen bg-slate-100 text-slate-900"><div className="flex min-h-screen">
    <aside className="hidden w-[248px] shrink-0 border-r border-slate-200 bg-white lg:flex lg:flex-col"><div className="flex h-[76px] items-center gap-3 border-b border-slate-100 px-6"><img src="/brand/tr-crest.webp" className="h-10 w-10 rounded-full object-cover" alt="TR Sports Line"/><div><div className="text-sm font-extrabold">TR SPORTS LINE</div><div className="text-[10px] text-slate-400">Store admin</div></div></div><nav className="flex-1 space-y-1 p-3">{navigation.map(({ id, label, icon: Icon }) => <button key={id} onClick={() => setPanel(id)} className={`flex w-full items-center gap-3 rounded-lg px-3 py-2.5 text-left text-[13px] font-semibold transition ${panel === id ? "bg-lime-100 text-lime-900" : "text-slate-600 hover:bg-slate-50"}`}><Icon size={17}/>{label}{panel === id && <ChevronRight size={14} className="ml-auto"/>}</button>)}</nav><div className="border-t border-slate-100 p-4"><a href="/" target="_blank" className="block text-xs font-semibold text-slate-500 hover:text-lime-700">View storefront ↗</a><button onClick={() => void logout()} className="mt-3 flex items-center gap-2 text-xs font-semibold text-slate-500 hover:text-red-600"><LogOut size={14}/> Sign out</button></div></aside>
    <div className="min-w-0 flex-1"><header className="sticky top-0 z-20 flex h-[68px] items-center justify-between border-b border-slate-200 bg-white/95 px-4 backdrop-blur sm:px-7"><div><div className="text-[10px] font-bold uppercase tracking-widest text-slate-400">Store management</div><div className="text-sm font-bold">{current.label}</div></div><div className="flex items-center gap-2"><a href="/" target="_blank" className="rounded-lg border border-slate-200 px-3 py-2 text-[11px] font-semibold text-slate-600 lg:hidden">Store ↗</a><ThemeToggle compact/><button onClick={() => void load()} title="Refresh data" className="grid h-9 w-9 place-items-center rounded-lg border border-slate-200 text-slate-500 hover:bg-slate-50"><RefreshCw size={15} className={loading ? "animate-spin" : ""}/></button><button onClick={() => void logout()} title="Sign out" className="grid h-9 w-9 place-items-center rounded-lg border border-slate-200 text-slate-500 hover:text-red-600"><LogOut size={15}/></button></div></header>
      <div className="border-b border-slate-200 bg-white px-3 py-2 lg:hidden"><div className="flex gap-1 overflow-x-auto">{navigation.map(({ id, label }) => <button key={id} onClick={() => setPanel(id)} className={`shrink-0 rounded-md px-3 py-2 text-[10px] font-bold ${panel === id ? "bg-slate-900 text-white" : "text-slate-500 hover:bg-slate-100"}`}>{label}</button>)}</div></div>
      <div className="mx-auto max-w-[1500px] p-4 sm:p-7 xl:p-9">{error && <div role="alert" className="mb-5 flex items-center justify-between rounded-lg border border-red-200 bg-red-50 px-4 py-3 text-sm text-red-700">{error}<button onClick={() => setError("")}><X size={16}/></button></div>}{notice && <div role="status" className="mb-5 flex items-center gap-2 rounded-lg border border-lime-200 bg-lime-50 px-4 py-3 text-sm text-lime-900"><Check size={15}/>{notice}</div>}

      {panel === "overview" && <><div className="mb-7 flex flex-wrap items-end justify-between gap-3"><div><h1 className="text-2xl font-extrabold tracking-tight">Good to see you.</h1><p className="mt-1 text-sm text-slate-500">Here is what is happening in your store.</p></div><a href="/" target="_blank" className="rounded-lg bg-slate-900 px-4 py-2.5 text-xs font-bold text-white">Open storefront ↗</a></div><div className="grid grid-cols-2 gap-3 xl:grid-cols-4">{[{ label: "Total orders", value: dashboardCounts.orders, icon: PackageCheck }, { label: "Catalog products", value: dashboardCounts.products, icon: Boxes }, { label: "Awaiting verification", value: dashboardCounts.pending, icon: CircleUserRound }, { label: "Order value", value: money(dashboardCounts.value), icon: BadgeDollarSign }].map(({ label, value, icon: Icon }) => <div key={label} className="rounded-xl border border-slate-200 bg-white p-4 sm:p-5"><div className="flex items-center justify-between text-xs font-semibold text-slate-500"><span>{label}</span><Icon size={17} className="text-lime-700"/></div><div className="mt-4 text-2xl font-extrabold">{value}</div></div>)}</div><section className="mt-7 rounded-xl border border-slate-200 bg-white"><div className="flex items-center justify-between border-b border-slate-100 px-5 py-4"><div><h2 className="font-bold">Recent orders</h2><p className="mt-1 text-xs text-slate-400">Latest customer purchases</p></div><button onClick={() => setPanel("orders")} className="text-xs font-bold text-lime-800">View orders →</button></div><OrdersTable orders={orders.slice(0, 6)} onUpdate={updateOrder}/></section></>}

      {panel === "orders" && <><div className="flex flex-wrap items-end justify-between gap-3"><PageHeading title="Orders" description="Review payment details, customer addresses and fulfillment progress."/><button onClick={() => window.print()} className="rounded-lg border border-slate-300 bg-white px-4 py-2.5 text-xs font-bold text-slate-700"><FileText size={14} className="mr-1 inline"/>Print order list</button></div><section className="mt-5 overflow-hidden rounded-xl border border-slate-200 bg-white"><OrdersTable orders={orders} onUpdate={updateOrder}/></section></>}

      {panel === "products" && <><PageHeading title="Products" description="Edit your catalog, image assets, price, stock and search metadata."/><div className="mt-5 grid gap-5 2xl:grid-cols-[minmax(0,1fr)_400px]"><section className="overflow-x-auto rounded-xl border border-slate-200 bg-white"><table className="w-full min-w-[740px] text-left text-xs"><thead className="bg-slate-50 text-[10px] uppercase tracking-wide text-slate-500"><tr>{["Product", "Category", "Price", "Stock", "Status", ""].map((text) => <th className="px-4 py-3" key={text}>{text}</th>)}</tr></thead><tbody>{products.map((product) => <tr key={product.id} className="border-t border-slate-100"><td className="px-4 py-3"><div className="flex items-center gap-3"><img src={product.image_url} alt="" className="h-12 w-10 rounded object-cover"/><div><strong className="block">{product.name}</strong><span className="text-[10px] text-slate-400">/{product.slug}</span></div></div></td><td className="px-4 py-3">{product.category}</td><td className="px-4 py-3 font-bold">{money(product.price)}</td><td className="px-4 py-3">{product.stock}</td><td className="px-4 py-3"><button onClick={() => void save(`/admin/products/${product.id}`, "PATCH", { is_active: !product.is_active }, "Visibility updated.")} className={`rounded-full px-2.5 py-1 text-[10px] font-bold ${product.is_active ? "bg-emerald-50 text-emerald-700" : "bg-slate-100 text-slate-500"}`}>{product.is_active ? "Active" : "Hidden"}</button></td><td className="px-4 py-3"><button onClick={() => { setEditingProduct(product.id); setProductForm(product); window.scrollTo({ top: 0, behavior: "smooth" }); }} className="font-bold text-lime-800">Edit</button></td></tr>)}</tbody></table></section><form onSubmit={createProduct} className="grid content-start gap-4 rounded-xl border border-slate-200 bg-white p-5"><div><h2 className="font-bold">{editingProduct ? "Edit product" : "Add a product"}</h2><p className="mt-1 text-xs text-slate-400">All product prices are USD.</p></div><Field label="Product name"><input required value={productForm.name || ""} onChange={(e) => setProductForm({ ...productForm, name: e.target.value })} className={inputClass}/></Field><Field label="URL slug"><input required value={productForm.slug || ""} onChange={(e) => setProductForm({ ...productForm, slug: e.target.value.toLowerCase().replace(/[^a-z0-9-]/g, "-") })} className={inputClass}/></Field><div className="grid grid-cols-2 gap-3"><Field label="Price (USD)"><input required type="number" step="0.01" min="0" value={productForm.price ?? 0} onChange={(e) => setProductForm({ ...productForm, price: Number(e.target.value) })} className={inputClass}/></Field><Field label="Stock"><input type="number" min="0" value={productForm.stock ?? 0} onChange={(e) => setProductForm({ ...productForm, stock: Number(e.target.value) })} className={inputClass}/></Field></div><div className="grid grid-cols-2 gap-3"><Field label="Category"><input value={productForm.category || ""} onChange={(e) => setProductForm({ ...productForm, category: e.target.value })} className={inputClass}/></Field><Field label="Edition"><select value={productForm.edition || "Fan Edition"} onChange={(e) => setProductForm({ ...productForm, edition: e.target.value })} className={inputClass}><option>Fan Edition</option><option>Player Edition</option></select></Field></div><Field label="Club / collection"><input value={productForm.club || ""} onChange={(e) => setProductForm({ ...productForm, club: e.target.value })} className={inputClass}/></Field><Field label="Description"><textarea rows={3} value={productForm.description || ""} onChange={(e) => setProductForm({ ...productForm, description: e.target.value })} className={inputClass}/></Field><ImageUpload label="Product image" value={productForm.image_url || ""} onChange={(image_url) => setProductForm({ ...productForm, image_url })} token={token}/><Field label="SEO title"><input value={productForm.meta_title || ""} onChange={(e) => setProductForm({ ...productForm, meta_title: e.target.value })} className={inputClass}/></Field><Field label="SEO description"><textarea rows={2} value={productForm.meta_description || ""} onChange={(e) => setProductForm({ ...productForm, meta_description: e.target.value })} className={inputClass}/></Field><div className="flex gap-2"><button disabled={saving} className="flex flex-1 items-center justify-center gap-2 rounded-lg bg-slate-900 px-4 py-2.5 text-xs font-bold text-white"><Save size={14}/>{saving ? "Saving…" : editingProduct ? "Save product" : "Create product"}</button>{editingProduct && <button type="button" onClick={() => { setEditingProduct(null); setProductForm({}); }} className="rounded-lg border border-slate-200 px-3 text-xs font-semibold">Cancel</button>}</div></form></div></>}

      {(panel === "homepage" || panel === "product_page") && <><PageHeading title={panel === "homepage" ? "Homepage settings" : "Product page settings"} description={panel === "homepage" ? "Control homepage sections, copy, visibility, order and desktop/mobile images." : "Edit the product experience copy and product page section content."}/><div className="mt-5 space-y-4">{(sections[panel === "homepage" ? "home" : "product"] || []).map((section, index) => <section key={`${section.id || section.section_key}`} className="rounded-xl border border-slate-200 bg-white"><div className="flex flex-wrap items-center justify-between gap-3 border-b border-slate-100 px-4 py-3"><div className="flex items-center gap-2"><span className="grid h-7 w-7 place-items-center rounded-md bg-slate-100 text-[10px] font-bold text-slate-500">{index + 1}</span><div><div className="text-sm font-bold">{section.section_key.replaceAll("_", " ")}</div><div className="text-[10px] text-slate-400">section key: {section.section_key}</div></div></div><div className="flex items-center gap-3"><Field label="Order"><input type="number" min="0" value={section.sort_order} onChange={(e) => updateSection(panel === "homepage" ? "home" : "product", index, { sort_order: Number(e.target.value) })} className="w-[80px] rounded-md border border-slate-200 px-2 py-1.5 text-xs"/></Field><label className="flex items-center gap-2 text-xs font-semibold text-slate-600"><input type="checkbox" checked={section.is_active} onChange={(e) => updateSection(panel === "homepage" ? "home" : "product", index, { is_active: e.target.checked })} className="accent-lime-700"/> Visible</label><button title="Remove section" onClick={() => setSections((current) => ({ ...current, [panel === "homepage" ? "home" : "product"]: current[panel === "homepage" ? "home" : "product"].filter((_, i) => i !== index) }))} className="rounded-md p-2 text-slate-400 hover:bg-red-50 hover:text-red-600"><Trash2 size={15}/></button></div></div><div className="grid gap-4 p-4 md:grid-cols-2"><Field label="Section heading"><input value={section.title || ""} onChange={(e) => updateSection(panel === "homepage" ? "home" : "product", index, { title: e.target.value })} className={inputClass}/></Field><Field label="Supporting text"><input value={section.subtitle || ""} onChange={(e) => updateSection(panel === "homepage" ? "home" : "product", index, { subtitle: e.target.value })} className={inputClass}/></Field><Field label="Long description"><textarea rows={2} value={section.body || ""} onChange={(e) => updateSection(panel === "homepage" ? "home" : "product", index, { body: e.target.value })} className={inputClass}/></Field><div className="grid gap-3"><ImageUpload label="Desktop / section image" value={section.image_url || ""} onChange={(image_url) => updateSection(panel === "homepage" ? "home" : "product", index, { image_url })} token={token}/>{section.section_key === "hero" && <ImageUpload label="Mobile hero image" value={section.mobile_image_url || ""} onChange={(mobile_image_url) => updateSection("home", index, { mobile_image_url })} token={token}/>}</div><div className="grid grid-cols-2 gap-3"><Field label="Button label"><input value={section.button_label || ""} onChange={(e) => updateSection(panel === "homepage" ? "home" : "product", index, { button_label: e.target.value })} className={inputClass}/></Field><Field label="Button link"><input value={section.button_url || ""} onChange={(e) => updateSection(panel === "homepage" ? "home" : "product", index, { button_url: e.target.value })} className={inputClass}/></Field></div></div></section>)}<div className="flex flex-wrap justify-between gap-2"><button onClick={() => addSection(panel === "homepage" ? "home" : "product")} className="inline-flex items-center gap-2 rounded-lg border border-slate-300 bg-white px-4 py-2.5 text-xs font-bold text-slate-700"><Plus size={14}/> Add section</button><button disabled={saving} onClick={() => saveSections(panel === "homepage" ? "home" : "product")} className="inline-flex items-center gap-2 rounded-lg bg-slate-900 px-5 py-2.5 text-xs font-bold text-white"><Save size={14}/> Save page settings</button></div></div>{panel === "homepage" && <section className="mt-6 rounded-xl border border-slate-200 bg-white p-5"><div className="mb-4 flex items-start justify-between"><div><h2 className="font-bold">Hero carousel banners</h2><p className="mt-1 text-xs text-slate-500">Upload separate wide and mobile crops for each slide.</p></div></div><div className="grid gap-3 md:grid-cols-2">{banners.map((banner) => <div key={banner.id} className="rounded-lg border border-slate-200 p-3"><div className="flex items-center gap-3"><img src={banner.desktop_image} alt="" className="h-14 w-20 rounded object-cover"/><div className="min-w-0 flex-1"><div className="truncate text-xs font-bold">{banner.title}</div><button onClick={() => void save(`/admin/banners/${banner.id}`, "PUT", { ...banner, is_active: !banner.is_active }, "Banner updated.")} className="mt-1 text-[10px] font-bold text-lime-800">{banner.is_active ? "Visible · click to hide" : "Hidden · click to show"}</button></div><button onClick={() => void save(`/admin/banners/${banner.id}`, "DELETE", {}, "Banner deleted.")} className="p-2 text-slate-400 hover:text-red-600"><Trash2 size={14}/></button></div></div>)}</div><form onSubmit={async (e) => { e.preventDefault(); await save("/admin/banners", "POST", { ...bannerForm, is_active: true }, "Banner added."); }} className="mt-5 grid gap-3 border-t border-slate-100 pt-5 md:grid-cols-2"><Field label="Banner title"><input required value={bannerForm.title || ""} onChange={(e) => setBannerForm({ ...bannerForm, title: e.target.value })} className={inputClass}/></Field><Field label="Banner subtitle"><input value={bannerForm.subtitle || ""} onChange={(e) => setBannerForm({ ...bannerForm, subtitle: e.target.value })} className={inputClass}/></Field><ImageUpload label="Desktop banner" value={bannerForm.desktop_image || ""} onChange={(desktop_image) => setBannerForm({ ...bannerForm, desktop_image })} token={token}/><ImageUpload label="Mobile crop" value={bannerForm.mobile_image || ""} onChange={(mobile_image) => setBannerForm({ ...bannerForm, mobile_image })} token={token}/><Field label="Button label"><input value={bannerForm.button_label || ""} onChange={(e) => setBannerForm({ ...bannerForm, button_label: e.target.value })} className={inputClass}/></Field><Field label="Button URL"><input value={bannerForm.button_url || ""} onChange={(e) => setBannerForm({ ...bannerForm, button_url: e.target.value })} className={inputClass}/></Field><button className="rounded-lg bg-slate-900 px-4 py-2.5 text-xs font-bold text-white md:col-span-2"><Plus size={14} className="mr-1 inline"/>Add hero banner</button></form></section>}</>}

      {panel === "pricing" && <><PageHeading title="Price table" description="Manage fabric prices, offer prices, minimum quantities and finishing add-ons for each product group."/><div className="mt-5 space-y-4">{groups.map((group, gi) => <PricingEditor key={group.id || group.slug} group={group} onChange={(next) => setGroups((current) => current.map((item, index) => index === gi ? next : item))} onRemove={() => setGroups((current) => current.filter((_, index) => index !== gi))}/>)}</div><div className="mt-4 flex flex-wrap justify-between gap-2"><button onClick={() => setGroups((current) => [...current, { name: "New product", slug: `new-product-${Date.now()}`, currency: "BDT", note: "", sort_order: current.length, is_active: true, entries: [{ fabric: "Plain Polyester", moq: 10, price: 0, offer_price: null, sort_order: 0 }], addons: [] }])} className="inline-flex items-center gap-2 rounded-lg border border-slate-300 bg-white px-4 py-2.5 text-xs font-bold"><Plus size={14}/> Add price group</button><button onClick={() => void save("/admin/pricing", "PUT", { groups }, "Price table saved.")} disabled={saving} className="inline-flex items-center gap-2 rounded-lg bg-slate-900 px-5 py-2.5 text-xs font-bold text-white"><Save size={14}/>{saving ? "Saving…" : "Save price table"}</button></div></>}

      {panel === "footer" && <><PageHeading title="Footer settings" description="Update footer identity, contact details and social links across the storefront."/><section className="mt-5 grid gap-4 rounded-xl border border-slate-200 bg-white p-5 md:grid-cols-2">{[["footer_tagline", "Brand tagline"], ["footer_address", "Address / delivery note"], ["footer_phone", "Phone number"], ["footer_email", "Support email"], ["footer_whatsapp", "WhatsApp number (country code)"], ["footer_instagram", "Instagram URL"], ["footer_facebook", "Facebook URL"]].map(([key, title]) => <Field key={key} label={title}><input value={settings[key] || ""} onChange={(e) => updateSettings(key, e.target.value)} className={inputClass}/></Field>)}<div className="md:col-span-2"><ImageUpload label="Footer logo" value={settings.footer_logo_url || "/brand/tr-crest.webp"} onChange={(url) => updateSettings("footer_logo_url", url)} token={token}/></div><div className="md:col-span-2"><button onClick={() => void save("/admin/settings", "PUT", { settings }, "Footer settings saved.")} className="inline-flex items-center gap-2 rounded-lg bg-slate-900 px-5 py-2.5 text-xs font-bold text-white"><Save size={14}/> Save footer</button></div></section></>}

      {panel === "media" && <><PageHeading title="Media library" description="Upload and reuse image assets throughout the storefront."/><section className="mt-5 rounded-xl border border-slate-200 bg-white p-5"><ImageUpload label="Upload image" value="" onChange={(url) => { setNotice(`Uploaded ${url}`); void load(); }} token={token}/><div className="mt-6 grid grid-cols-2 gap-3 sm:grid-cols-3 lg:grid-cols-5 xl:grid-cols-6">{media.map((file) => <button key={file.url} title={file.name} onClick={() => { void navigator.clipboard?.writeText(file.url); setNotice("Image URL copied."); }} className="overflow-hidden rounded-lg border border-slate-200 text-left hover:border-lime-500"><img src={file.url} alt={file.name} className="aspect-square w-full bg-slate-50 object-cover"/><span className="block truncate p-2 text-[10px] font-semibold text-slate-600">{file.name}</span></button>)}</div>{media.length === 0 && <p className="py-12 text-center text-sm text-slate-400">Uploaded images appear here.</p>}</section></>}

      {panel === "coupons" && <><PageHeading title="Coupons" description="Create discount codes and turn active promotions on or off."/><div className="mt-5 grid gap-5 xl:grid-cols-[minmax(0,1fr)_360px]"><section className="overflow-x-auto rounded-xl border border-slate-200 bg-white"><table className="w-full min-w-[620px] text-left text-xs"><thead className="bg-slate-50 text-[10px] uppercase text-slate-500"><tr>{["Code", "Discount", "Minimum order", "Expires", "Status", ""].map((x) => <th key={x} className="px-4 py-3">{x}</th>)}</tr></thead><tbody>{coupons.map((coupon) => <tr key={coupon.id} className="border-t border-slate-100"><td className="px-4 py-3 font-extrabold">{coupon.code}</td><td className="px-4 py-3">{coupon.type === "percent" ? `${coupon.value}%` : money(coupon.value)}</td><td className="px-4 py-3">{money(coupon.min_order || 0)}</td><td className="px-4 py-3">{coupon.expires_at ? new Date(coupon.expires_at).toLocaleDateString() : "No expiry"}</td><td className="px-4 py-3"><button onClick={() => void save(`/admin/coupons/${coupon.id}`, "PATCH", { is_active: !coupon.is_active }, "Coupon status updated.")} className="font-bold text-lime-800">{coupon.is_active ? "Active" : "Paused"}</button></td><td className="px-4 py-3"><button onClick={() => void save(`/admin/coupons/${coupon.id}`, "DELETE", {}, "Coupon deleted.")} className="text-slate-400 hover:text-red-600"><Trash2 size={14}/></button></td></tr>)}</tbody></table>{coupons.length === 0 && <p className="p-8 text-center text-sm text-slate-400">No coupons created.</p>}</section><form onSubmit={async (e) => { e.preventDefault(); const form = e.currentTarget; const f = new FormData(form); await save("/admin/coupons", "POST", { code: String(f.get("code")).toUpperCase(), type: f.get("type"), value: Number(f.get("value")), min_order: Number(f.get("min_order") || 0), is_active: true }); form.reset(); }} className="grid content-start gap-4 rounded-xl border border-slate-200 bg-white p-5"><h2 className="font-bold">New coupon</h2><Field label="Coupon code"><input required name="code" className={inputClass} placeholder="MATCHDAY10"/></Field><div className="grid grid-cols-2 gap-3"><Field label="Discount type"><select name="type" className={inputClass}><option value="fixed">Fixed USD</option><option value="percent">Percent</option></select></Field><Field label="Value"><input required name="value" type="number" min="1" className={inputClass}/></Field></div><Field label="Minimum order (USD)"><input name="min_order" type="number" min="0" defaultValue="0" className={inputClass}/></Field><button className="rounded-lg bg-slate-900 px-4 py-2.5 text-xs font-bold text-white"><Plus size={14} className="mr-1 inline"/>Create coupon</button></form></div></>}

      {panel === "reviews" && <><PageHeading title="Customer reviews" description="Publish verified reviews and delivery photos in the storefront social proof gallery."/><div className="mt-5 grid gap-5 xl:grid-cols-[minmax(0,1fr)_380px]"><section className="grid content-start gap-3">{reviews.map((review) => <article key={review.id} className="flex gap-3 rounded-xl border border-slate-200 bg-white p-4">{review.photo_url ? <img src={review.photo_url} alt="" className="h-16 w-16 rounded-lg object-cover"/> : <div className="grid h-16 w-16 place-items-center rounded-lg bg-slate-100 text-amber-500"><Star size={19}/></div>}<div className="min-w-0 flex-1"><div className="flex flex-wrap items-center gap-2"><strong className="text-sm">{review.customer_name}</strong><span className="text-[10px] text-slate-400">{review.district} · {"★".repeat(review.rating)}</span></div><p className="mt-1 text-xs leading-5 text-slate-600">{review.review}</p><div className="mt-2 flex gap-3"><button onClick={() => void save(`/admin/reviews/${review.id}`, "PATCH", { is_published: !review.is_published }, "Review visibility updated.")} className="text-[10px] font-bold text-lime-800">{review.is_published ? "Published · hide" : "Hidden · publish"}</button><button onClick={() => void save(`/admin/reviews/${review.id}`, "PATCH", { is_verified: !review.is_verified }, "Review verification updated.")} className="text-[10px] font-bold text-slate-500">{review.is_verified ? "Verified · unverify" : "Not verified · verify"}</button><button onClick={() => void save(`/admin/reviews/${review.id}`, "DELETE", {}, "Review removed.")} className="text-[10px] font-bold text-red-600">Delete</button></div></div></article>)}{reviews.length === 0 && <p className="rounded-xl border border-slate-200 bg-white p-8 text-center text-sm text-slate-400">No reviews yet.</p>}</section><form onSubmit={async (e) => { e.preventDefault(); const form = e.currentTarget; const f = new FormData(form); await save("/admin/reviews", "POST", { customer_name: f.get("customer_name"), district: f.get("district"), review: f.get("review"), photo_url: reviewPhoto || null, rating: Number(f.get("rating")), is_verified: f.get("is_verified") === "on", is_published: f.get("is_published") === "on" }, "Review added."); setReviewPhoto(""); form.reset(); }} className="grid content-start gap-4 rounded-xl border border-slate-200 bg-white p-5"><h2 className="font-bold">Add review</h2><Field label="Customer name"><input required name="customer_name" className={inputClass}/></Field><Field label="District"><input required name="district" className={inputClass}/></Field><Field label="Review"><textarea required name="review" rows={4} className={inputClass}/></Field><ImageUpload label="Customer delivery photo" value={reviewPhoto} onChange={setReviewPhoto} token={token}/><Field label="Rating"><select name="rating" className={inputClass}>{[5,4,3,2,1].map((n) => <option key={n} value={n}>{n} stars</option>)}</select></Field><label className="text-xs"><input name="is_verified" type="checkbox" className="mr-2 accent-lime-700"/>Verified purchase</label><label className="text-xs"><input name="is_published" type="checkbox" className="mr-2 accent-lime-700"/>Publish now</label><button className="rounded-lg bg-slate-900 px-4 py-2.5 text-xs font-bold text-white"><Plus size={14} className="mr-1 inline"/>Add review</button></form></div></>}

      {panel === "settings" && <><PageHeading title="Store settings" description="Delivery charges, checkout rules, tracking and site search metadata."/><div className="mt-5 grid gap-5 xl:grid-cols-2"><section className="rounded-xl border border-slate-200 bg-white p-5"><h2 className="font-bold">Checkout and fees</h2><div className="mt-4 grid gap-3 sm:grid-cols-2">{[["customization_fee", "Name / number fee (USD)"], ["edition_surcharge", "Player fit adjustment (USD)"], ["patch_fee", "Patch fee (USD)"], ["bkash_merchant_number", "bKash merchant number"], ["nagad_merchant_number", "Nagad merchant number"]].map(([key, title]) => <Field key={key} label={title}><input value={settings[key] || ""} onChange={(e) => updateSettings(key, e.target.value)} className={inputClass}/></Field>)}</div><label className="mt-4 flex items-center gap-2 text-xs font-semibold"><input type="checkbox" checked={settings.partial_advance_enabled !== "0"} onChange={(e) => updateSettings("partial_advance_enabled", e.target.checked ? "1" : "0")} className="accent-lime-700"/> Require delivery advance for custom print orders</label><h3 className="mt-6 text-sm font-bold">Delivery zones</h3><div className="mt-3 grid gap-2">{zones.map((zone, i) => <div key={zone.name} className="grid grid-cols-[1fr_110px_auto] items-center gap-2"><input value={zone.name} onChange={(e) => setZones((all) => all.map((row, index) => index === i ? { ...row, name: e.target.value } : row))} className={inputClass}/><input type="number" min="0" value={zone.charge} onChange={(e) => setZones((all) => all.map((row, index) => index === i ? { ...row, charge: Number(e.target.value) } : row))} className={inputClass} aria-label="Delivery charge in USD"/><button onClick={() => setZones((all) => all.map((row, index) => index === i ? { ...row, is_active: !row.is_active } : row))} className="px-2 text-[10px] font-bold text-lime-800">{zone.is_active ? "Active" : "Hidden"}</button></div>)}</div><button onClick={() => setZones((all) => [...all, { name: "New delivery zone", charge: 0, is_active: true }])} className="mt-3 inline-flex items-center gap-1 text-xs font-bold text-lime-800"><Plus size={13}/> Add zone</button></section><section className="rounded-xl border border-slate-200 bg-white p-5"><h2 className="font-bold">SEO, tracking and product page</h2><div className="mt-4 grid gap-3">{[["seo_site_title", "Site title"], ["seo_site_description", "Site description"], ["seo_site_keywords", "Search keywords"], ["product_page_badge", "Product badge"], ["product_page_delivery_note", "Product delivery note"], ["product_page_size_note", "Size chart note"], ["gtm_id", "Google Tag Manager ID"], ["facebook_pixel_id", "Facebook Pixel ID"], ["facebook_capi_access_token", "Facebook CAPI token"], ["facebook_test_event_code", "Test event code"]].map(([key, title]) => <Field key={key} label={title}><input type={key.includes("token") ? "password" : "text"} value={settings[key] || ""} onChange={(e) => updateSettings(key, e.target.value)} className={inputClass}/></Field>)}</div></section><button onClick={() => void save("/admin/settings", "PUT", { settings, delivery_zones: zones }, "Store settings saved.")} className="inline-flex w-fit items-center gap-2 rounded-lg bg-slate-900 px-5 py-2.5 text-xs font-bold text-white"><Save size={14}/> Save all settings</button></div></>}
      </div>
    </div>
  </div></main>;
}

function PageHeading({ title, description }: { title: string; description: string }) { return <div><h1 className="text-2xl font-extrabold tracking-tight">{title}</h1><p className="mt-1 text-sm text-slate-500">{description}</p></div>; }

function OrdersTable({ orders, onUpdate }: { orders: Order[]; onUpdate: (order: Order, patch: Partial<Order>) => void }) {
  return <div className="overflow-x-auto"><table className="w-full min-w-[900px] text-left text-xs"><thead className="bg-slate-50 text-[10px] uppercase tracking-wide text-slate-500"><tr>{["Order", "Customer", "Payment", "Total", "Progress"].map((text) => <th key={text} className="px-4 py-3">{text}</th>)}</tr></thead><tbody>{orders.map((order) => <tr key={order.id} className="border-t border-slate-100 align-top"><td className="px-4 py-3"><strong>{order.order_number}</strong><div className="mt-1 text-[10px] text-slate-400">{order.items?.length || 0} items</div></td><td className="px-4 py-3"><strong>{order.customer_name}</strong><div className="mt-1 text-[10px] text-slate-500">{order.phone} · {order.district}</div><div className="mt-1 max-w-[240px] text-[10px] text-slate-400">{order.address}</div></td><td className="px-4 py-3"><div className="font-semibold">{order.payment_method}</div><select value={order.payment_status} onChange={(e) => onUpdate(order, { payment_status: e.target.value })} className="mt-2 rounded-md border border-slate-200 bg-white px-2 py-1.5 text-[10px]"><option value="pending">Pending</option><option value="pending_review">Needs review</option><option value="paid">Paid / verified</option><option value="failed">Failed</option></select></td><td className="px-4 py-3 font-bold">{money(order.total)}</td><td className="px-4 py-3"><select value={order.status} onChange={(e) => onUpdate(order, { status: e.target.value })} className="rounded-md border border-slate-200 bg-white px-2 py-2 text-[10px]"><option value="order_placed">Order placed</option><option value="printing">Printing / heat-press</option><option value="handed_to_courier">Handed to courier</option><option value="delivered">Delivered</option><option value="cancelled">Cancelled</option></select><input aria-label="Courier service" defaultValue={order.courier || ""} placeholder="Courier" onBlur={(e) => e.target.value !== (order.courier || "") && onUpdate(order, { courier: e.target.value })} className="mt-2 block w-full rounded-md border border-slate-200 px-2 py-1.5 text-[10px]"/><input aria-label="Courier tracking code" defaultValue={order.courier_tracking_code || ""} placeholder="Tracking code" onBlur={(e) => e.target.value !== (order.courier_tracking_code || "") && onUpdate(order, { courier_tracking_code: e.target.value })} className="mt-2 block w-full rounded-md border border-slate-200 px-2 py-1.5 text-[10px]"/><input aria-label="Courier tracking URL" defaultValue={order.courier_tracking_url || ""} placeholder="Tracking URL" onBlur={(e) => e.target.value !== (order.courier_tracking_url || "") && onUpdate(order, { courier_tracking_url: e.target.value })} className="mt-2 block w-full rounded-md border border-slate-200 px-2 py-1.5 text-[10px]"/></td></tr>)}</tbody></table>{orders.length === 0 && <p className="p-8 text-center text-sm text-slate-400">No orders to show yet.</p>}</div>;
}

function PricingEditor({ group, onChange, onRemove }: { group: PriceGroup; onChange: (group: PriceGroup) => void; onRemove: () => void }) {
  const update = (change: Partial<PriceGroup>) => onChange({ ...group, ...change });
  const setEntry = (index: number, change: Partial<PriceEntry>) => update({ entries: group.entries.map((row, i) => i === index ? { ...row, ...change } : row) });
  const setAddon = (index: number, change: Partial<PriceAddon>) => update({ addons: group.addons.map((row, i) => i === index ? { ...row, ...change } : row) });
  return <details open className="overflow-hidden rounded-xl border border-slate-200 bg-white"><summary className="flex cursor-pointer list-none items-center justify-between gap-3 px-4 py-4"><div className="flex items-center gap-3"><ChevronDown size={15} className="text-slate-400"/><strong className="text-sm">{group.name}</strong><span className="rounded-full bg-slate-100 px-2 py-1 text-[9px] font-bold uppercase text-slate-500">{group.currency}</span></div><button type="button" onClick={(e) => { e.preventDefault(); onRemove(); }} className="p-2 text-slate-400 hover:text-red-600"><Trash2 size={14}/></button></summary><div className="border-t border-slate-100 p-4"><div className="grid gap-3 sm:grid-cols-[1fr_140px_1fr_auto]"><Field label="Product type"><input value={group.name} onChange={(e) => update({ name: e.target.value })} className={inputClass}/></Field><Field label="Currency"><select value={group.currency} onChange={(e) => update({ currency: e.target.value as PriceGroup["currency"] })} className={inputClass}><option value="BDT">BDT / tk</option><option value="USD">USD / $</option></select></Field><Field label="Price note"><input value={group.note || ""} onChange={(e) => update({ note: e.target.value })} className={inputClass}/></Field><label className="flex items-end gap-2 pb-2 text-xs font-semibold"><input type="checkbox" checked={group.is_active} onChange={(e) => update({ is_active: e.target.checked })} className="accent-lime-700"/> Published</label></div><div className="mt-5 flex items-center justify-between"><h3 className="text-xs font-bold uppercase tracking-wide text-slate-500">Fabric price rows</h3><button onClick={() => update({ entries: [...group.entries, { fabric: "New fabric", moq: null, price: 0, offer_price: null, sort_order: group.entries.length }] })} className="text-[11px] font-bold text-lime-800"><Plus size={12} className="mr-1 inline"/>Add row</button></div><div className="mt-2 overflow-x-auto rounded-lg border border-slate-200"><table className="w-full min-w-[640px] text-left text-[11px]"><thead className="bg-slate-50 text-[9px] uppercase text-slate-500"><tr>{["Fabric", "MOQ (pcs)", `Price (${group.currency})`, `Offer (${group.currency})`, ""].map((text) => <th className="px-2 py-2" key={text}>{text}</th>)}</tr></thead><tbody>{group.entries.map((row, index) => <tr key={row.id || index} className="border-t border-slate-100"><td className="p-1.5"><input value={row.fabric} onChange={(e) => setEntry(index, { fabric: e.target.value })} className="w-full rounded border border-slate-200 px-2 py-1.5"/></td><td className="p-1.5"><input type="number" min="1" value={row.moq || ""} onChange={(e) => setEntry(index, { moq: e.target.value ? Number(e.target.value) : null })} className="w-24 rounded border border-slate-200 px-2 py-1.5" placeholder="—"/></td><td className="p-1.5"><input type="number" min="0" value={row.price} onChange={(e) => setEntry(index, { price: Number(e.target.value) })} className="w-28 rounded border border-slate-200 px-2 py-1.5"/></td><td className="p-1.5"><input type="number" min="0" value={row.offer_price ?? ""} onChange={(e) => setEntry(index, { offer_price: e.target.value ? Number(e.target.value) : null })} className="w-28 rounded border border-slate-200 px-2 py-1.5" placeholder="—"/></td><td className="p-1.5"><button onClick={() => update({ entries: group.entries.filter((_, i) => i !== index) })} className="p-2 text-slate-400 hover:text-red-600"><Trash2 size={13}/></button></td></tr>)}</tbody></table></div><div className="mt-5 flex items-center justify-between"><h3 className="text-xs font-bold uppercase tracking-wide text-slate-500">Sleeves, necks and add-ons</h3><button onClick={() => update({ addons: [...group.addons, { category: "addon", label: "New add-on", amount: 0, sort_order: group.addons.length }] })} className="text-[11px] font-bold text-lime-800"><Plus size={12} className="mr-1 inline"/>Add option</button></div><div className="mt-2 grid gap-2 md:grid-cols-2">{group.addons.map((addon, index) => <div key={addon.id || index} className="grid grid-cols-[130px_1fr_110px_36px] items-center gap-2"><select value={addon.category} onChange={(e) => setAddon(index, { category: e.target.value as PriceAddon["category"] })} className="rounded-md border border-slate-200 bg-white px-2 py-2 text-[10px]"><option value="sleeve">Sleeve</option><option value="neck">Neck</option><option value="addon">Add-on</option></select><input value={addon.label} onChange={(e) => setAddon(index, { label: e.target.value })} className="min-w-0 rounded-md border border-slate-200 px-2 py-2 text-xs"/><input type="number" min="0" value={addon.amount} onChange={(e) => setAddon(index, { amount: Number(e.target.value) })} className="rounded-md border border-slate-200 px-2 py-2 text-xs" aria-label="Option price"/><button onClick={() => update({ addons: group.addons.filter((_, i) => i !== index) })} className="grid h-8 w-8 place-items-center rounded text-slate-400 hover:bg-red-50 hover:text-red-600"><Trash2 size={13}/></button></div>)}</div></div></details>;
}
